using System;using System.IO;using System.Linq;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Data;
namespace InputAtlas {public partial class MainWindow {
 int shortcutGeneration;bool hideShiftShortcuts=true,hideModifierShortcuts;string shortcutSearch="";
 async void ShortcutPage(){int request=++shortcutGeneration;Heading("Key combinations","快捷键统计");
  var filters=new WrapPanel{Margin=new Thickness(0,0,0,12)};var shift=new CheckBox{Content=T("Hide Shift-only combinations","隐藏仅含 Shift 的组合"),IsChecked=hideShiftShortcuts,Margin=new Thickness(0,0,20,8)};var modifiers=new CheckBox{Content=T("Hide modifier-only combinations","隐藏纯修饰键组合"),IsChecked=hideModifierShortcuts,Margin=new Thickness(0,0,0,8)};filters.Children.Add(shift);filters.Children.Add(modifiers);page.Children.Add(filters);
  page.Children.Add(Txt(T("Search combinations","搜索快捷键"),12));var search=new TextBox{Text=shortcutSearch,Width=290,HorizontalAlignment=HorizontalAlignment.Left,Margin=new Thickness(0,0,0,12),ToolTip=T("Search combinations, for example Ctrl + C","搜索组合，例如 Ctrl + C")};page.Children.Add(search);var loading=Txt(T("Loading key combinations…","正在读取快捷键…"),12);page.Children.Add(loading);
  DateTime end=to.SelectedDate.Value.Date,start=mode.SelectedIndex==4?new DateTime(1970,1,1):Store.Period(end,mode.SelectedIndex);
  try{var data=await Task.Run(()=>ShortcutStore.Read(Store.Root,start,end,0));if(request!=shortcutGeneration||tabs.SelectedIndex!=7)return;page.Children.Remove(loading);
   var summary=Txt("",14);page.Children.Add(summary);var view=new ListCollectionView(data.Rows);var table=new DataGrid{ItemsSource=view,AutoGenerateColumns=false,IsReadOnly=true,CanUserAddRows=false,HeadersVisibility=DataGridHeadersVisibility.Column,GridLinesVisibility=DataGridGridLinesVisibility.Horizontal,MinColumnWidth=130,MinHeight=150,MaxHeight=620,EnableRowVirtualization=true,Margin=new Thickness(0,0,0,14)};
   table.Columns.Add(new DataGridTextColumn{Header=T("Combination","快捷键"),Binding=new Binding("Combination"),MinWidth=260,Width=new DataGridLength(1,DataGridLengthUnitType.Star)});table.Columns.Add(new DataGridTextColumn{Header=T("Used","使用次数"),Binding=new Binding("Count"){StringFormat="N0"},Width=160});page.Children.Add(table);
   Action apply=()=>{hideShiftShortcuts=shift.IsChecked==true;hideModifierShortcuts=modifiers.IsChecked==true;shortcutSearch=search.Text;view.Filter=o=>{var r=(ShortcutRow)o;return !(hideShiftShortcuts&&r.ShiftOnly)&&!(hideModifierShortcuts&&r.ModifierOnly)&&(String.IsNullOrWhiteSpace(shortcutSearch)||r.Combination.Replace(" ","").IndexOf(shortcutSearch.Replace(" ",""),StringComparison.OrdinalIgnoreCase)>=0);};summary.Text=T("Combinations shown: ","当前显示组合：")+view.Count+T(" · Uses: "," · 使用次数：")+view.Cast<ShortcutRow>().Sum(r=>r.Count).ToString("N0");};shift.Click+=(s,e)=>apply();modifiers.Click+=(s,e)=>apply();search.TextChanged+=(s,e)=>apply();apply();
   AddNote("A new physical press counts once while held modifiers are combined as Ctrl / Alt / Shift / Win. Holding a key does not repeatedly increase its shortcut count. Modifier-only chords count when released. These totals overlap with ordinary keystrokes.","按住 Ctrl／Alt／Shift／Win 时，新的实体按键按下一次计一次组合；持续长按按键计作一次。纯修饰键组合在松开时确认。快捷键次数与普通按键统计分别展示。");
  }catch(Exception ex){if(request==shortcutGeneration&&tabs.SelectedIndex==7)loading.Text=T("Shortcut read status: ","快捷键读取状态：")+ex.Message;}
 }
}}
